def d2logpdf_dlink2(self, link_f, y, Y_metadata=None):
        """
        Hessian at y, given link(f), w.r.t link(f)
        i.e. second derivative logpdf at y given link(f_i) and link(f_j)  w.r.t link(f_i) and link(f_j)
        The hessian will be 0 unless i == j

        .. math::
            \\frac{d^{2} \\ln p(y_{i}|\lambda(f_{i}))}{d^{2}\\lambda(f)} = -\\beta^{2}\\frac{d\\Psi(\\alpha_{i})}{d\\alpha_{i}}\\\\
            \\alpha_{i} = \\beta y_{i}

        :param link_f: latent variables link(f)
        :type link_f: Nx1 array
        :param y: data
        :type y: Nx1 array
        :param Y_metadata: Y_metadata which is not used in gamma distribution
        :returns: Diagonal of hessian matrix (second derivative of likelihood evaluated at points f)
        :rtype: Nx1 array

        .. Note::
            Will return diagonal of hessian, since every where else it is 0, as the likelihood factorizes over cases
            (the distribution for y_i depends only on link(f_i) not on link(f_(j!=i))
        """
        y_{i}|\\theta,f_{i})}{d f_{i}^{2}} = \\frac{d^{2} \\ln p(y_{i}|\\theta,f_{i})}{d f_{i}^{2}}

                .. math::
                    = \\frac{d^{2} \\ln p(y_{i}|\\theta,f_{i})}{d f_{i}^{2}} = \\frac{d^{2} \\ln p(y_{i}|\\theta,f_{i})}{d f_{i}^{2}}

                :param link_f: latent variable, i.e., link(f)
                :param y: data
                :return: Hessian at y, given link(f), w.r.t link(f)
                """
                if Y_metadata is None:
                    Y_metadata = {}
                if Y_metadata.get("model_type") == "regression":
                    return self._d2logpdf_dlink2_dlink2(link_f, y, Y_metadata)
                elif Y_metadata.get("model_type") == "classification":
                    return self._d2logpdf_dlink2_dlink2(link_f, y, Y_metadata)
                else:
                    raise NotImplementedError

